'use strict';
const KEY='frota-em-dia-v1';
function uid(){const bytes=new Uint8Array(16);crypto.getRandomValues(bytes);return Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');}
const icons={bus:'<rect x="3" y="3" width="18" height="16" rx="3"/><path d="M3 11h18M8 3v8M16 3v8M6 19v2M18 19v2M7 15h.01M17 15h.01"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',fuel:'<path d="M4 21V4h10v17M2 21h14M4 10h10M17 4l3 3v10a2 2 0 0 1-4 0v-5h-2M18 5v4h2"/>',chart:'<path d="M4 3v18h17M8 16v-5M13 16V7M18 16V4"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',alert:'<path d="m12 3 10 18H2L12 3ZM12 9v4M12 17h.01"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',meter:'<path d="M3 18a10 10 0 1 1 18 0M12 13l5-5M6 16h12"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6l8-4Z"/><path d="m8 12 3 3 5-6"/>',wrench:'<path d="M21 3a6 6 0 0 1-8 8L5 21l-3-3 10-8a6 6 0 0 1 8-8l-4 4 3 3 4-4"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.bus}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>n==null?'—':new Intl.NumberFormat('pt-BR',{maximumFractionDigits:0}).format(n);
const dec=n=>n==null?'—':new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(n);
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n);
const fmt=s=>s?dateObj(s.slice(0,10)).toLocaleDateString('pt-BR'):'Não informado';
const labels={red:'Urgente',yellow:'Atenção',green:'Em dia',pending:'A conferir'};
const badge=(s,text)=>`<span class="tag ${s}">${esc(text||labels[s])}</span>`;
const btn=(action,text,ic='',cls='',id='',extra='')=>`<button class="${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''} ${extra}>${ic?icon(ic):''}${text}</button>`;
let state;let page='fleet',selected=null,tab='overview',query='',filter='all',alertFilter='all',companyFilter='all';let saveError=false;
function blankVehicle(fields){return{id:uid(),...fields,documents:{},services:{},tires:['Dianteiro esquerdo','Dianteiro direito','Traseiro esquerdo','Traseiro direito','Estepe'].map(position=>({position,serial:'',size:'',brand:'',km:null,date:''})),equipment:Object.fromEntries(RULES.equipment.map(x=>[x,'unknown'])),checked:'',fuel:[],history:[]}}
function emptyState(){return {version:1,demo:false,vehicles:[],profiles:[]}}
state=emptyState();
function vehicleSummary(v){return [v.category,v.year,v.capacity?capacityText(v):'',v.fuelType].filter(Boolean).map(esc).join(' · ')}
function validateData(s){if(s?.version!==1||!Array.isArray(s.vehicles)||s.vehicles.length>2000)throw Error('Arquivo de backup incompatível.');const seen=new Set();for(const v of s.vehicles){if(!v.id||typeof v.id!=='string'||!/^[A-Z]{3}[0-9][A-Z0-9][0-9]{2}$/.test(v.plate)||seen.has(v.plate)||(v.km!==null&&(!Number.isFinite(v.km)||v.km<0))||typeof v.model!=='string'||!v.documents||!v.services||!Array.isArray(v.tires)||!v.equipment||!Array.isArray(v.fuel)||!Array.isArray(v.history))throw Error('Backup com dados inválidos.');seen.add(v.plate);for(const e of v.fuel)if(!Number.isFinite(e.km)||!Number.isFinite(e.liters)||!Number.isFinite(e.total)||e.liters<=0||e.total<0||v.km==null||e.km>v.km||typeof e.date!=='string')throw Error('Abastecimento inválido no backup.');for(const d of Object.values(v.documents))if(d.due&&!/^\d{4}-\d{2}-\d{2}$/.test(d.due))throw Error('Validade inválida no backup.');}return s}
async function persist(){return saveShared()}
function log(v,text,date=dateOnly()){const person=currentProfile();v.history.unshift({id:uid(),date,text,actorId:person?.id||'',actorName:person?.name||''})}
function toast(text){const t=document.getElementById('toast');t.textContent=text;t.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.style.display='none',5000)}
const getV=id=>state.vehicles.find(x=>x.id===id);
function allAlerts(){return state.vehicles.flatMap(v=>vehicleAlerts(v)).sort((a,b)=>({red:0,yellow:1,pending:2}[a.level]-{red:0,yellow:1,pending:2}[b.level]))}
function shell(){if(novaAuth.stage!=='ready')return renderNovaAccess();const count=allAlerts().filter(a=>a.level!=='pending').length;document.getElementById('app').innerHTML=`<aside class="sidebar"><div class="brand"><div class="brand-icon"><img src="nova-alianca-symbol.svg" alt=""></div><div><strong>Nova Aliança</strong><small>TRANSPORTES</small></div></div><nav class="nav" aria-label="Principal">${novaNavigation().map(([p,l,i])=>`<button data-action="nav" data-id="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}${l}${p==='alerts'&&count?`<span class="count">${count}</span>`:''}</button>`).join('')}</nav><div class="sidebar-foot"><span class="local-dot"></span><b><span id="sync-label">${sharedStatus==='online'?(novaAuth.session?.hosted?'Sincronizado online':'Sincronizado na LAN'):sharedStatus==='saving'?'Salvando na empresa…':'Sem conexão com o servidor'}</span></b><br>Mogi das Cruzes · SP<br>Frota e equipe em movimento.</div></aside><main class="main"><header class="topbar"><div class="crumb">Seu dia a dia <span style="margin:0 11px;color:#bec8bd">/</span> <strong>${selected?'Detalhes do veículo':{today:'Hoje',fleet:'Minha frota',school:'Chamadas',point:'Meu ponto',employees:'Equipe',alerts:'Alertas',fuel:'Abastecimentos',reports:'Resumo da frota',settings:'Ajustes'}[page]}</strong></div><div class="mobile-brand"><img src="nova-alianca-symbol.svg" alt=""><span>Nova Aliança<small>TRANSPORTES</small></span></div><div class="right"><span class="date">${new Date().toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo',day:'numeric',month:'long',year:'numeric'})}</span>${novaCurrentUser()?.role!=='employee'?`<button class="text" data-action="nav" data-id="alerts" aria-label="Ver alertas">${icon('bell')}</button>`:''}${profileControl()}</div></header><div class="content">${sharedNotice()}${state.demo?`<div class="demo"><span><strong>Frota de exemplo</strong> · Explore o app. Estes veículos são fictícios.</span>${btn('start','Cadastrar minha frota')}</div>`:''}${selected?detailView(getV(selected)):page==='today'?experienceTodayView():page==='school'?schoolView():page==='point'?novaPointView():page==='employees'?novaEmployeesView():page==='fleet'?fleetView():page==='alerts'?alertsView():page==='fuel'?fuelView():page==='reports'?reportsView():settingsView()}<div class="footer-note">Nova Aliança Transportes · Mogi das Cruzes, SP</div></div></main>`;if(selected&&tab==='overview')initVehicleTracking();if(page==='fleet'&&!selected){document.getElementById('operating-filter')?.addEventListener('change',e=>{operatingFilter=e.target.value;document.getElementById('vehicle-grid').innerHTML=vehicleCards()});document.getElementById('company-filter')?.addEventListener('change',e=>{companyFilter=e.target.value;document.getElementById('vehicle-grid').innerHTML=vehicleCards()});document.getElementById('search')?.addEventListener('input',e=>{query=e.target.value;document.getElementById('vehicle-grid').innerHTML=vehicleCards()})}}
function pageHead(title,sub,actions=''){return`<div class="page-head"><div><h1>${title}</h1><p class="sub">${sub}</p></div><div class="actions">${actions}</div></div>`}
function fleetView(){const counts={all:state.vehicles.length,red:0,yellow:0,green:0};state.vehicles.forEach(v=>counts[vehicleStatus(v)]++);const upcoming=allAlerts().filter(a=>a.level!=='pending');return`<div class="na-company-strip"><span>${icon('pin')} Mogi das Cruzes · SP</span><span>Nova Aliança Transportes</span></div>${pageHead('Nossa frota','Veículos, cuidados e próximos compromissos.',btn('fuel-add','Abastecer','fuel')+btn('vehicle-add','Novo veículo','plus','primary'))}<div class="stats">${[['all','Veículos na frota','bus',''],['green','Tudo em dia','check','green'],['yellow','Precisam de atenção','clock','yellow'],['red','Precisam de ação','alert','red']].map(([k,l,i,c])=>`<button data-action="filter" data-id="${k}" class="stat ${c}" aria-label="${l}: ${counts[k]}"><div><span class="label stat-label-desktop">${l}</span><span class="label stat-label-mobile">${{all:'Veículos',green:'Em dia',yellow:'Atenção',red:'Urgentes'}[k]}</span><span class="value">${String(counts[k]).padStart(2,'0')}</span></div><span class="stat-icon">${icon(i)}</span></button>`).join('')}</div>${upcoming.length?`<div class="notice">${icon('bell')}<div><strong>${upcoming.length} pendência${upcoming.length>1?'s':''} para acompanhar</strong><p>Documentos e manutenções próximos do prazo ou já vencidos.</p></div>${btn('nav','Ver alertas '+icon('arrow'),'','','alerts')}</div>`:''}<div class="section-head"><h2>Seus veículos <small>(${state.vehicles.length})</small></h2><small>Organizados por placa</small></div><div class="tools company-tools">${companyOptions()}${operationalFilterControl()}<label class="search">${icon('search')}<input id="search" value="${esc(query)}" placeholder="Buscar placa, modelo ou motorista" aria-label="Buscar veículo"></label><div class="filters" aria-label="Filtrar por situação">${[['all','Todos'],['green','Em dia'],['yellow','Atenção'],['red','Urgentes']].map(([k,l])=>btn('filter',l,'',filter===k?'active':'',k,`aria-pressed="${filter===k}"`)).join('')}</div></div><div class="fleet-grid" id="vehicle-grid">${vehicleCards()}</div>`}
function vehicleCards(){const q=query.toLocaleLowerCase('pt-BR').replace(/[-\s]/g,'');const list=state.vehicles.filter(v=>(!SHOW_COMPANY_GROUPS||companyFilter==='all'||(v.company||'__unassigned')===companyFilter)&&`${v.plate}${v.model}${v.driver}${SHOW_COMPANY_GROUPS?v.company||'':''}`.toLocaleLowerCase('pt-BR').replace(/[-\s]/g,'').includes(q)&&(filter==='all'||vehicleStatus(v)===filter)&&(operatingFilter==='all'||(v.operating?.status||'unknown')===operatingFilter)).sort((a,b)=>a.plate.localeCompare(b.plate));if(!list.length)return`<div class="empty full">${icon('bus')}<h2>${state.vehicles.length?'Nenhum veículo encontrado':'Sua frota começa aqui'}</h2><p>${state.vehicles.length?'Tente outra placa ou mude o filtro.':'Cadastre o primeiro veículo para acompanhar os cuidados.'}</p>${btn(state.vehicles.length?'reset-filter':'vehicle-add',state.vehicles.length?'Limpar busca e filtros':'Cadastrar veículo','plus','primary')}</div>`;return list.map(v=>{const status=vehicleStatus(v),a=vehicleAlerts(v).sort((x,y)=>({red:0,yellow:1,pending:2}[x.level]-{red:0,yellow:1,pending:2}[y.level]))[0];return`<article class="vehicle"><div class="vehicle-top"><span class="plate">${esc(v.plate)}</span>${badge(status)}</div><div class="vehicle-model">${esc(v.model||'Modelo não informado')}</div><div class="vehicle-type">${vehicleSummary(v)}</div>${operatingBadge(v)}${SHOW_COMPANY_GROUPS?`<div class="vehicle-company">${esc(v.company||'Empresa não informada')}</div>`:''}<div class="vehicle-info"><div class="info-line">${icon('user')}Motorista<span>${esc(v.driver||'Não informado')}</span></div><div class="info-line">${icon('pin')}Cidade<span>${esc(v.city||'Não informada')}</span></div><div class="info-line">${icon('meter')}Quilometragem<span>${v.km==null?'Não informada':num(v.km)+' km'}</span></div></div><div class="vehicle-alert ${a?.level||''}">${icon(a?'alert':'check')}<span>${a?`${esc(a.title)} · ${esc(a.detail)}`:'Documentos e manutenção em dia'}</span></div><div class="vehicle-footer">${btn('detail','Ver veículo '+icon('arrow'),'','',v.id)}${btn('fuel-add','Abastecer','fuel','',v.id)}</div></article>`}).join('')}
function detailView(v){if(!v){selected=null;return fleetView()}const stats=fuelMetrics(v.fuel);return`${btn('back','Voltar para a frota','back','text back')}<div class="page-head"><div><div class="detail-heading"><span class="plate">${esc(v.plate)}</span>${badge(vehicleStatus(v))}</div><h1>${esc(v.model||'Modelo não informado')}</h1><p class="sub">${esc(v.year)} · ${esc(v.city||'Cidade não informada')} · ${v.km==null?'Não informada':num(v.km)+' km'}</p></div><div class="actions">${v.source?.kind==='photo-table'?btn('complete-identity','Completar identificação','plus','',v.id):''}${btn('operation','Editar operação','user','',v.id)}${btn('fuel-add','Abastecer','fuel','primary',v.id)}</div></div><div class="tabs" aria-label="Informações do veículo">${[['overview','Visão geral'],['routine','Rotina'],['documents','Documentos'],['maintenance','Manutenção'],['tires','Pneus'],['equipment','Equipamentos'],['history','Histórico']].map(([k,l])=>btn('tab',l,'',tab===k?'active':'',k,tab===k?'aria-current="page"':'')).join('')}</div>${tab==='overview'?`${trackingCard(v)}${operationalOverview(v)}${fipeView(v)}${importReviewView(v)}${publicResearchView(v)}<div class="detail-grid"><section class="panel"><h2>Identificação do veículo</h2><p class="help">Identificação fixa, informada no cadastro.${v.source?.kind==='photo-table'?' Dados conferidos com as fotografias da planilha.':v.source?' Dados da consulta pública: conferir no documento.':''}</p><dl class="facts">${[['Placa',v.plate],...(SHOW_COMPANY_GROUPS?[['Empresa',v.company]]:[]),['Categoria',v.category],['Cor',v.color],['Ano / modelo',v.year],['Ano de fabricação',v.manufactureYear],['Chassi (VIN)',v.chassis],...(v.chassisModel?[['Modelo comercial do chassi',v.chassisModel]]:[]),['Número do câmbio',v.gearbox],['Capacidade veicular',v.capacity?capacityText(v):''],['Combustível',v.fuelType]].map(([k,x])=>`<div><dt>${k}</dt><dd>${esc(x||'Não informado')}</dd></div>`).join('')}</dl></section><section class="panel"><h2>Na rotina</h2><dl class="facts">${[['Motorista',v.driver],['Monitora',v.monitor],['Cidade',v.city],['Linha',v.route],['Hodômetro',v.km==null?'':num(v.km)+' km'],['Consumo médio',stats.average?dec(stats.average)+' km/L':'Aguardando registros']].map(([k,x])=>`<div><dt>${k}</dt><dd>${esc(x||'Não informado')}</dd></div>`).join('')}</dl></section></div>${technicalSpecsView(v)}<section class="panel"><div class="section-head"><h2>O que merece atenção</h2><small>${vehicleAlerts(v).length} item(ns)</small></div>${alertRows(vehicleAlerts(v))||'<p class="help">Tudo em dia. Nenhuma pendência encontrada nos dados registrados.</p>'}</section>`:tab==='routine'?routineView(v):tab==='documents'?documentsView(v):tab==='maintenance'?maintenanceView(v):tab==='tires'?tiresView(v):tab==='equipment'?equipmentView(v):historyView(v)}`}
function alertRows(list){return list.map(a=>{const v=getV(a.vehicle);return`<div class="row"><div class="alert-symbol ${a.level}">${icon(a.level==='red'?'alert':'clock')}</div><div class="grow"><strong>${esc(a.title)}</strong><p>${esc(a.detail)}${selected?'':` · <b>${esc(v?.plate)}</b>`}</p></div>${badge(a.level)}${btn('resolve','Conferir '+icon('arrow'),'','',a.vehicle,`data-section="${a.section}"`)}</div>`}).join('')}
function documentsView(v){return`<div class="rule-note">Aviso com 30 dias de antecedência. Vistoria: 6 meses; licenciamento e seguro: 12 meses. Intervalos interpretados do briefing, sujeitos à confirmação. Tacógrafo e extintor usam a validade informada.</div><section class="panel" style="margin-top:20px"><h2>Documentos e validades</h2>${RULES.documents.map(r=>{const d=v.documents[r.key];const left=d?.due?daysUntil(d.due):null;const s=d?.applicability==='not-applicable'?'pending':left==null?'pending':left<0?'red':left<=30?'yellow':'green';return`<div class="row"><div class="grow"><strong>${r.name}</strong><p>${d?.applicability==='not-applicable'?'Não se aplica · '+esc(d.applicabilityReason):d?.due?`Válido até ${fmt(d.due)}${r.months?' · ciclo de '+r.months+' meses':''}${d?.annotation?' · marcação '+esc(d.annotation)+' na planilha':''}`:d?.status==='invalid'?'Data inválida na planilha: '+d.rawValue:d?.status==='uncertain'?'Data da fotografia a confirmar':d?.present==='no'?'Não possui • conferir necessidade':'Validade ainda não informada'}</p></div>${d?.applicability==='not-applicable'?'<span>Não se aplica</span>':badge(s)}${btn('document-applicability','Aplicabilidade','','',v.id,`data-key="${r.key}"`)}${btn('document-edit',d?'Atualizar':'Informar','','',v.id,`data-key="${r.key}"`)}</div>`}).join('')}</section>`}
function maintenanceView(v){return`${issuesView(v)}<div class="rule-note">Óleo e filtro: a cada 9.000 km. Preventiva: a cada 90 dias. Serviços sem intervalo definido ficam no histórico. Aviso por quilometragem começa a 1.000 km do limite (padrão adotado).</div><section class="panel" style="margin-top:20px"><h2>Cuidados com o veículo</h2>${RULES.services.map(r=>{const s=v.services[r.key],due=r.km&&s?.km!=null?s.km+r.km:null;return`<div class="row"><div class="grow"><strong>${r.name}</strong><p>Último serviço: ${fmt(s?.date)}${s?.km!=null?' · '+num(s.km)+' km':''}</p><p>${due?'Próxima troca aos '+num(due)+' km':r.days&&s?.date?'Próxima em '+fmt(addDate(s.date,r.days)):'Sem prazo automático definido'}</p></div>${btn('service-edit','Registrar serviço','plus','',v.id,`data-key="${r.key}"`)}</div>`}).join('')}</section>`}
function tiresView(v){return`<div class="rule-note">Cada pneu tem seu próprio registro, incluindo o estepe. Intervalo de acompanhamento: 40.000 km desde a instalação. Ao trocar, os dados anteriores ficam no histórico. O intervalo não substitui a inspeção física.</div><section class="panel" style="margin-top:20px"><div class="section-head"><h2>Pneus do veículo</h2>${btn('tire-add','Adicionar posição','plus','',v.id)}</div>${v.tires.map((t,i)=>`<div class="row"><div class="grow"><strong>${esc(t.position)}</strong><p>${esc(t.brand||'Marca não informada')} · ${esc(t.size||'Medida não informada')} · Nº ${esc(t.serial||'—')}</p><p>${t.km!=null?`Instalado em ${fmt(t.date)} · ${num(t.km)} km · acompanhar troca aos ${num(t.km+RULES.tireKm)} km`:'Instalação ainda não registrada'}</p></div>${btn('tire-edit',t.serial?'Registrar troca':'Cadastrar pneu','','',v.id,`data-key="${i}"`)}</div>`).join('')}</section>`}
function equipmentView(v){return`<section class="panel"><h2>Conferência de equipamentos</h2><p class="help">Última conferência: ${fmt(v.checked)}. Problemas ficam em vermelho; itens ausentes ou a conferir ficam em amarelo no formulário.</p><form id="equipment-form" data-vehicle="${esc(v.id)}"><div class="equipment">${RULES.equipment.map((name,i)=>`<label>${name}<select name="eq${i}" aria-label="${name}">${[['unknown','A conferir'],['ok','Possui e está funcionando'],['no','Não possui'],['bad','Possui, com problema']].map(([k,l])=>`<option value="${k}" ${v.equipment[name]===k?'selected':''}>${l}</option>`).join('')}</select></label>`).join('')}</div><p class="help">A ausência é registrada para conferência, sem presumir quais itens são obrigatórios.</p><button type="submit" class="primary">${icon('check')}Salvar conferência</button></form></section>`}
function fuelTable(entries){return entries.length?`<div class="table-wrap"><table><thead><tr><th>Veículo</th><th>Data / hora</th><th>Hodômetro</th><th>Litros</th><th>Total</th><th>Tanque</th><th>Registrado por</th></tr></thead><tbody>${entries.map(e=>`<tr><td><strong>${esc(e.plate)}</strong></td><td>${fmt(e.date)} ${esc(e.date.slice(11,16))}</td><td>${num(e.km)} km</td><td>${dec(e.liters)} L</td><td>${money(e.total)}</td><td>${e.full?'Cheio':'Parcial'}</td><td>${esc(e.recordedBy?.name||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="help">Nenhum abastecimento registrado ainda.</p>'}
function historyView(v){return`<section class="panel"><h2>Abastecimentos</h2><p class="help">Média de consumo calculada entre tanques cheios, incluindo os abastecimentos parciais do intervalo.</p>${fuelTable(v.fuel.map(e=>({...e,plate:v.plate})).sort((a,b)=>b.date.localeCompare(a.date)))}</section><section class="panel"><h2>Histórico de alterações e serviços</h2>${v.history.length?v.history.map(h=>`<div class="row"><div class="grow"><strong>${esc(h.text)}</strong><p>${fmt(h.date)}${h.recordedBy?.name||h.actorName?`<span class="profile-author">por ${esc(h.recordedBy?.name||h.actorName)}</span>`:''}</p></div></div>`).join(''):'<p class="help">Os próximos registros aparecerão aqui.</p>'}</section>`}
function alertsView(){const list=allAlerts().filter(a=>alertFilter==='all'||a.level===alertFilter);return`${pageHead('Alertas da frota','O que precisa de cuidado, por ordem de prioridade.')}<div class="rule-note">Os alertas são recalculados ao abrir o app e após cada registro. Esta versão não envia notificações com o app fechado.</div><div class="filters" style="margin:20px 0">${[['all','Todos'],['red','Urgentes'],['yellow','Próximos do prazo'],['pending','Dados a conferir']].map(([k,l])=>btn('alert-filter',l,'',alertFilter===k?'active':'',k)).join('')}</div><section class="panel alert-list">${alertRows(list)||'<div class="empty">'+icon('check')+'<h2>Nenhum alerta nesta categoria</h2><p>Os próximos avisos aparecerão aqui.</p></div>'}</section>`}
function fuelView(){const entries=state.vehicles.flatMap(v=>v.fuel.map(e=>({...e,plate:v.plate}))).sort((a,b)=>b.date.localeCompare(a.date));return`${pageHead('Abastecimentos','Registre o tanque. A quilometragem e os alertas se atualizam juntos.',btn('fuel-add','Registrar abastecimento','plus','primary'))}<section class="panel"><h2>Registros da frota</h2><p class="help">O primeiro tanque cheio inicia a medição. O próximo fecha o intervalo de consumo.</p>${fuelTable(entries)}</section>`}
function reportsView(){const entries=state.vehicles.flatMap(v=>v.fuel),liters=entries.reduce((s,e)=>s+e.liters,0),total=entries.reduce((s,e)=>s+e.total,0);return`${pageHead('Resumo da frota','Números simples para acompanhar o dia a dia.')}<div class="report-grid"><section class="panel"><p class="eyebrow">Combustível registrado</p><div class="metric">${dec(liters)} <small>L</small></div></section><section class="panel"><p class="eyebrow">Gasto total registrado</p><div class="metric">${money(total)}</div></section><section class="panel"><p class="eyebrow">Abastecimentos</p><div class="metric">${entries.length}</div></section></div><section class="panel" style="margin-top:22px"><h2>Consumo por veículo</h2><p class="help">Média ponderada por litros em intervalos completos de tanque cheio a tanque cheio. Registros parciais são acumulados.</p><div class="table-wrap"><table><thead><tr><th>Placa</th><th>Modelo</th><th>Média</th><th>Último intervalo</th></tr></thead><tbody>${[...state.vehicles].sort((a,b)=>a.plate.localeCompare(b.plate)).map(v=>{const m=fuelMetrics(v.fuel);return`<tr><td>${btn('detail',esc(v.plate),'','text',v.id)}</td><td>${esc(v.model||'Modelo não informado')}</td><td>${m.average?dec(m.average)+' km/L':'Aguardando registros'}</td><td>${m.last?dec(m.last)+' km/L':'—'}</td></tr>`}).join('')}</tbody></table></div></section>`}
function settingsView(){return`${pageHead('Ajustes','Cuide dos seus dados e entenda as regras do app.')}<section class="panel na-company-card"><img src="nova-alianca-logo.svg" alt="Nova Aliança Transportes"><dl><div><dt>Empresa</dt><dd>Nova Aliança Transportes</dd></div><div><dt>Cidade</dt><dd>Mogi das Cruzes · SP</dd></div><div><dt>Responsável</dt><dd>Agenilto</dd></div></dl></section>${teamView()}<section class="panel"><h2>Seus dados</h2><p>${novaAuth.session?.hosted?'Os registros da empresa ficam no armazenamento privado online. Celulares e computadores entram com a própria conta e consultam a mesma frota.':'Os registros da empresa ficam salvos no PC que mantém o servidor aberto. Celulares e computadores conectados à LAN consultam a mesma frota.'} As alterações aparecem automaticamente nos outros aparelhos; durante o preenchimento de um formulário, a atualização aguarda para preservar o que está sendo digitado.</p><div class="actions">${btn('export','Exportar frota','download','primary')}${btn('import','Importar frota','plus')}${novaCurrentUser()?.role==='admin'?novaButton('backup-full','Backup completo')+(novaAuth.session?.hosted?novaButton('restore-full','Restaurar backup completo'):''):''}</div><p class="help">Este arquivo contém somente veículos e seus registros. Não inclui contas, ponto ou chamadas. A importação substitui a frota da empresa para todos os aparelhos após confirmação. Faça um backup antes.</p></section><section class="panel"><h2>Como funcionam os avisos</h2><dl class="facts">${[['Documentos','Amarelo até 30 dias antes; vermelho após vencer.'],['Óleo e filtro','9.000 km desde a última troca.'],['Manutenção preventiva','90 dias desde o último serviço.'],['Pneus individuais','40.000 km desde a instalação.'],['Aviso por quilometragem','1.000 km antes (padrão adotado).'],['Campos fixos','Placa, modelo, ano, chassi, câmbio e combustível. A capacidade atual pode ser confirmada na aba Rotina.']].map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl><p class="rule-note">Vistoria semestral; licenciamento e seguro anuais: interpretações do briefing a confirmar. As regras estão em rules.js e podem ser alteradas pelo código. Não representam orientação legal.</p><p class="help">Itens sem data ou registro são tratados como “A conferir”, nunca como “Em dia”. O app não decide se um veículo está autorizado a circular.</p></section><section class="panel"><h2>Limites desta versão</h2><p class="help">${novaAuth.session?.hosted?'Frota, ponto e chamadas compartilhados online. Não é necessário manter o PC da empresa ligado para acessar.':'Frota compartilhada na LAN, sem sincronização em nuvem. O PC servidor deve permanecer ligado e com o CMD aberto.'} O acesso depende da conta: funcionários consultam o próprio ponto; gestores acessam a frota; administradores gerenciam contas e horários. Os avisos aparecem dentro do app; não há envio de push, WhatsApp ou e-mail.</p>${state.demo?btn('start','Começar minha frota','plus'):''}</section>`}
function modal(title,sub,body,onSubmit,submit='Salvar'){const m=document.getElementById('modal');m.innerHTML=`<div class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2><p>${esc(sub)}</p></div><button type="button" data-action="close" aria-label="Fechar">${icon('close')}</button></div><form id="modal-form"><div class="modal-body">${body}<p id="form-error" class="error full" role="alert"></p></div><div class="modal-footer">${btn('close','Cancelar')}<button class="primary" type="submit">${submit}</button></div></form>`;m.querySelectorAll('[data-action="close"]').forEach(b=>b.type='button');m.showModal();m.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;if(form.dataset.submitting==='1')return;const token=novaCaptureSession(),data=new FormData(form),button=form.querySelector('[type=submit]'),label=button.textContent;form.dataset.submitting='1';button.disabled=true;button.textContent='Salvando…';try{await onSubmit(data,form)}catch(err){if(!err.staleSession&&novaSessionCurrent(token)){const error=form.querySelector('#form-error');if(error&&form.isConnected)error.textContent=err.message;else toast(err.message)}}finally{if(form.isConnected){delete form.dataset.submitting;button.disabled=false;button.textContent=label}}})}
const field=(name,label,type='text',value='',extra='',full=false)=>`<label class="${full?'full':''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(name,label,opts,value='',full=false)=>`<label class="${full?'full':''}">${label}<select name="${name}">${opts.map(o=>{const [k,l]=Array.isArray(o)?o:[o,o];return`<option value="${esc(k)}" ${value===k?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`;
function closeModal(){document.getElementById('modal').close()}
async function commit(message){if(saving)return;saving=true;closeModal();shell();document.querySelectorAll('button,input,select,textarea').forEach(el=>el.disabled=true);const ok=await persist();saving=false;if(ok)equipmentDirty=false;shell();if(ok)toast(message);return ok}
function vehicleAdd(){modal('Novo veículo','Cadastre a identificação. Os cuidados podem ser informados depois.',select('category','Tipo de veículo',['Transporte','Passeio','Carga','Implemento'],'Transporte',true)+field('plate','Placa','text','','required maxlength="8" placeholder="ABC1D23" autocapitalize="characters"')+field('model','Modelo','text','','required maxlength="80" placeholder="Ex.: Mercedes-Benz Sprinter"')+field('year','Ano / modelo','number','','required min="1950" max="2100" step="1"')+field('km','Quilometragem atual (km)','number','','required min="0" step="1"')+field('chassis','Chassi','text','','required maxlength="17" minlength="17"')+field('gearbox','Número do câmbio','text','','maxlength="40"')+field('capacity','Capacidade (passageiros)','number','','required min="1" max="200" step="1"')+select('fuelType','Combustível',['Diesel S10','Diesel S500','Gasolina','Etanol','Flex','GNV','Elétrico'])+(SHOW_COMPANY_GROUPS?field('company','Empresa','text','','maxlength="100"',true):'')+field('city','Cidade de operação','text','','maxlength="80"')+field('driver','Motorista','text','','maxlength="80"')+field('monitor','Monitora','text','','maxlength="80"')+field('route','Linha','text','','maxlength="100"')+'<p class="warn-box full">Confira antes de salvar: placa, modelo, ano, chassi, câmbio, capacidade e combustível não poderão ser editados depois.</p>',f=>{const plate=f.get('plate').trim().toUpperCase().replace(/[-\s]/g,'');if(!/^[A-Z]{3}[0-9][A-Z0-9][0-9]{2}$/.test(plate))throw Error('Informe uma placa válida, como ABC1234 ou ABC1D23.');if(state.vehicles.some(v=>v.plate===plate))throw Error('Esta placa já está cadastrada.');const chassis=f.get('chassis').trim().toUpperCase();if(!/^[A-HJ-NPR-Z0-9]{17}$/.test(chassis))throw Error('Confira o chassi: 17 letras e números, sem I, O ou Q.');const v=blankVehicle({plate,category:f.get('category'),company:String(f.get('company')||'').trim(),model:f.get('model').trim(),year:+f.get('year'),km:+f.get('km'),chassis,gearbox:f.get('gearbox').trim(),capacity:+f.get('capacity'),fuelType:f.get('fuelType'),city:f.get('city').trim(),driver:f.get('driver').trim(),monitor:f.get('monitor').trim(),route:f.get('route').trim()});if(!v.model)throw Error('Informe o modelo.');if(state.demo)state={version:1,demo:false,vehicles:[]};state.vehicles.push(v);log(v,'Veículo cadastrado');selected=v.id;tab='overview';page='fleet';commit('Veículo cadastrado. Complete os documentos e cuidados.');},'Cadastrar veículo')}
function operation(v){modal('Editar operação',v.plate,(SHOW_COMPANY_GROUPS?field('company','Empresa','text',v.company||'','maxlength="100"',true):'')+field('driver','Motorista','text',v.driver,'maxlength="80"')+field('monitor','Monitora','text',v.monitor,'maxlength="80"')+field('city','Cidade','text',v.city,'maxlength="80"')+field('route','Linha','text',v.route,'maxlength="100"'),f=>{for(const k of ['company','driver','monitor','city','route'])if(f.has(k))v[k]=f.get(k).trim();log(v,'Dados da operação atualizados');commit('Operação atualizada.')} )}
function localNow(){const d=new Date();return dateOnly()+'T'+new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(d)}
function fuelAdd(id){if(!state.vehicles.length){toast('Cadastre um veículo primeiro.');return vehicleAdd()}const v=getV(id)||state.vehicles[0];modal('Registrar abastecimento','Informe a quilometragem mostrada no painel.',select('vehicle','Veículo',state.vehicles.map(v=>[v.id,`${v.plate} · ${v.model}`]),v.id,true)+field('date','Data e hora','datetime-local',localNow(),`required max="${localNow()}"`)+field('km','Hodômetro (km)','number','','required min="0" step="1"')+field('liters','Quantidade (litros)','number','','required min="0.001" step="0.001"')+field('total','Valor total (R$)','number','','required min="0" step="0.01"')+field('driver','Motorista','text',v.driver,'maxlength="80"',true)+'<label class="check full"><input type="checkbox" name="full"> Encheu o tanque completamente?</label><p class="help full" id="fuel-hint"></p>',f=>{const target=getV(f.get('vehicle'));const km=+f.get('km'),liters=+f.get('liters'),total=+f.get('total'),date=f.get('date');const last=[...target.fuel].sort((a,b)=>b.date.localeCompare(a.date))[0];if(km<target.km)throw Error(`O hodômetro precisa ser igual ou maior que ${num(target.km)} km.`);if(date>localNow()||date.slice(0,10)>dateOnly())throw Error('A data não pode estar no futuro.');if(last&&date<last.date)throw Error('Registre os abastecimentos em ordem de data e hora.');if(liters<=0||!Number.isFinite(liters))throw Error('Informe uma quantidade válida de litros.');target.fuel.push({id:uid(),date,km,liters,total,full:f.get('full')==='on',driver:f.get('driver').trim()});target.km=km;log(target,`Abastecimento: ${dec(liters)} L · ${num(km)} km`,date.slice(0,10));commit('Abastecimento salvo. Quilometragem e alertas atualizados.');},'Salvar abastecimento');const form=document.getElementById('modal-form');const update=()=>{const t=getV(form.elements.vehicle.value);form.elements.km.min=t.km??0;form.elements.km.placeholder=t.km==null?'Informe a leitura do painel':num(t.km)+' ou mais';form.elements.driver.value=t.driver;document.getElementById('fuel-hint').textContent=`Último hodômetro: ${t.km==null?'não informado':num(t.km)+' km'}. A média será calculada entre tanques cheios.`};form.elements.vehicle.addEventListener('change',update);update()}
function documentEdit(v,key){const r=RULES.documents.find(x=>x.key===key),d=v.documents[key]||{};const body=(key==='extinguisher'?select('present','Possui extintor?',[['yes','Sim'],['no','Não']],d.present||'yes',true):'')+field('date',r.months?'Data da realização / renovação':'Data do registro','date',d.date||dateOnly(),`required max="${dateOnly()}"`,!r.months)+field('due','Data de validade','date',d.due||'',r.months?'required readonly':'',!r.months)+(r.months?`<p class="help full">Validade calculada: ${r.months} meses após a realização. O intervalo pode ser alterado no código.</p>`:'<p class="help full">Informe a validade indicada no documento ou equipamento.</p>');modal(r.name+' · '+v.plate,'O app avisa 30 dias antes da validade.',body,(f,form)=>{const present=f.get('present')||'yes',date=f.get('date');const due=r.months?addDate(date,r.months,'months'):f.get('due');if(present==='yes'&&!due)throw Error('Informe a validade.');if(date>dateOnly())throw Error('A realização não pode estar no futuro.');v.documents[key]={...d,date,due:present==='no'?'':due,present};log(v,`${r.name}: ${present==='no'?'ausente':`validade registrada em ${fmt(due)}`}`);commit('Validade registrada. Alertas atualizados.')});const f=document.getElementById('modal-form');if(r.months){const calc=()=>f.elements.due.value=addDate(f.elements.date.value||dateOnly(),r.months,'months');f.elements.date.addEventListener('input',calc);calc()}if(key==='extinguisher'){const change=()=>{const no=f.elements.present.value==='no';f.elements.due.disabled=no;f.elements.due.required=!no};f.elements.present.addEventListener('change',change);change()}}
function serviceEdit(v,key){const r=RULES.services.find(x=>x.key===key);modal(r.name+' · '+v.plate,'Registre somente um serviço realizado.',field('date','Data do serviço','date',dateOnly(),`required max="${dateOnly()}"`)+field('km','Hodômetro no serviço (km)','number',v.km,`required min="0" ${v.km==null?'':'max="'+v.km+'"'} step="1"`)+field('notes','Observações','text','','maxlength="500"',true),f=>{const date=f.get('date'),km=+f.get('km');if(date>dateOnly()||(v.km!=null&&km>v.km))throw Error('Data ou quilometragem acima do registro atual.');const old=v.services[key];if(old?.date&&date<old.date)throw Error('Use uma data igual ou posterior ao último serviço.');if(old?.km!=null&&km<old.km)throw Error('A quilometragem é menor que a do último serviço.');v.services[key]={date,km};log(v,`${r.name} realizado · ${num(km)} km${f.get('notes')?' · '+f.get('notes'):''}`,date);commit('Serviço registrado. Próximo prazo atualizado.')},'Registrar serviço')}
function tireEdit(v,index){const t=v.tires[index];modal('Pneu · '+esc(t.position),v.plate+' · Os dados anteriores ficam no histórico.',field('serial','Número / identificação','text','','required maxlength="60"')+field('brand','Marca','text','','required maxlength="60"')+field('size','Medida','text',t.size,'required maxlength="40" placeholder="225/75 R16"')+field('date','Data de instalação','date',dateOnly(),`required max="${dateOnly()}"`)+field('km','Hodômetro na instalação (km)','number',v.km,`required min="0" ${v.km==null?'':'max="'+v.km+'"'} step="1"`,true),f=>{if(f.get('date')>dateOnly()||(v.km!=null&&+f.get('km')>v.km))throw Error('Confira a data e a quilometragem.');if(t.km!=null&&+f.get('km')<t.km)throw Error('A quilometragem é anterior à última instalação.');if(t.serial)log(v,`Pneu retirado · ${t.position} · Nº ${t.serial} · ${t.brand} · ${t.size} · instalado em ${fmt(t.date)} aos ${num(t.km)} km`);for(const k of ['serial','brand','size','date'])t[k]=f.get(k).trim();t.km=+f.get('km');log(v,`Pneu instalado · ${t.position} · Nº ${t.serial} · ${t.brand} · ${t.size} · ${num(t.km)} km`,t.date);commit('Pneu atualizado. Histórico preservado.')},'Registrar pneu')}
function start(){modal('Começar sua frota','Os exemplos serão removidos.',`<p class="full help">O app ficará vazio para você cadastrar os veículos reais. Apenas os dados de demonstração serão removidos.</p>`,()=>{state={version:1,demo:false,vehicles:[]};selected=null;page='fleet';filter='all';query='';commit('Tudo pronto para cadastrar sua frota.')},'Remover exemplos')}
function exportData(){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=url;a.download=`frota-backup-${dateOnly()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Frota exportada. Contas, ponto e chamadas não estão neste arquivo.')}
function importData(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{const file=input.files[0];if(!file)return;if(file.size>10000000)throw Error('O arquivo excede 10 MB.');const data=validateData(JSON.parse(await file.text()));modal('Importar frota','Confira antes de substituir os veículos e seus registros.',`<p class="full help">O backup contém <strong>${data.vehicles.length} veículo(s)</strong>. A frota compartilhada da empresa será substituída em todos os aparelhos. Exporte um backup antes, se quiser mantê-la.</p>`,()=>{state=data;selected=null;commit('Frota importada.')},'Substituir e restaurar')}catch(err){toast(err.message||'Não foi possível ler o backup.')}});input.click()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id,act=b.dataset.action;if(saving)return;if(['vehicle-add','fuel-add','operation','document-edit','service-edit','tire-edit','tire-add','complete-identity','import','start','retry-save'].includes(act)&&!requireActiveProfile())return;const v=getV(id);if(['nav','tab','detail','back','resolve'].includes(act))equipmentDirty=false;switch(act){case'reconnect':return bootShared();case'retry-save':return commit('Alterações salvas na empresa.');case'recover-shared':return recoverShared().catch(e=>toast(e.message));case'nav':page=id;selected=null;query='';break;case'filter':filter=id;break;case'reset-filter':query='';filter='all';companyFilter='all';operatingFilter='all';break;case'detail':selected=id;tab='overview';page='fleet';break;case'resolve':selected=id;tab=b.dataset.section;page='fleet';break;case'back':selected=null;page='fleet';break;case'tab':tab=id;break;case'alert-filter':alertFilter=id;break;case'vehicle-add':return vehicleAdd();case'fuel-add':return fuelAdd(id);case'operation':return operation(v);case'complete-identity':return completeVehicleIdentity(v);case'document-applicability':return documentApplicability(v,b.dataset.key);case'document-edit':return v.documents[b.dataset.key]?.importSource?editSheetDocument(v,b.dataset.key):documentEdit(v,b.dataset.key);case'service-edit':return serviceEdit(v,b.dataset.key);case'tire-edit':return tireEdit(v,+b.dataset.key);case'tire-add':return modal('Adicionar posição de pneu',v.plate,field('position','Nome da posição','text','','required maxlength="60" placeholder="Ex.: Traseiro direito interno"',true),f=>{const position=f.get('position').trim();if(!position||v.tires.some(t=>t.position.toLowerCase()===position.toLowerCase()))throw Error('Use um nome de posição diferente.');v.tires.push({position,serial:'',size:'',brand:'',km:null,date:''});log(v,'Posição de pneu adicionada: '+position);commit('Posição adicionada. Cadastre o pneu.')});case'close':return closeModal();case'start':return start();case'export':return exportData();case'import':return importData();default:return}shell()});
document.addEventListener('submit',e=>{if(e.target.id!=='equipment-form')return;e.preventDefault();if(saving||!requireActiveProfile())return;const v=getV(e.target.dataset.vehicle),f=new FormData(e.target);for(let i=0;i<RULES.equipment.length;i++)v.equipment[RULES.equipment[i]]=f.get('eq'+i);v.checked=dateOnly();log(v,'Equipamentos conferidos: '+Object.entries(v.equipment).map(([k,s])=>`${k}: ${{ok:'OK',bad:'problema',no:'ausente',unknown:'a conferir'}[s]}`).join('; '));commit('Conferência salva.')});
document.getElementById('modal').addEventListener('click',e=>{if(e.target===e.currentTarget){const rect=e.currentTarget.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal()}});
document.getElementById('app').innerHTML='<div class="alinho-loading"><img src="nova-alianca-logo.svg" alt="Nova Aliança"><h1>Conectando à frota da empresa…</h1></div>';


function documentApplicability(v,key){const rule=RULES.documents.find(r=>r.key===key),d=v.documents[key]||{};modal('Aplicabilidade · '+rule.name,v.plate+' · Confirme com a administração.',opsSelect('applicability','Este item se aplica ao veículo?',[['unknown','A confirmar'],['applicable','Sim'],['not-applicable','Não se aplica']],d.applicability||'unknown')+opsArea('reason','Justificativa (obrigatória para não se aplica)',d.applicabilityReason||'',false,500)+'<p class="help full">A opção “Não se aplica” suspende os avisos deste item. As datas anteriores são preservadas. O app não determina dispensas automaticamente.</p>',f=>{const applicability=f.get('applicability'),reason=f.get('reason').trim();if(applicability==='not-applicable'&&reason.length<5)throw Error('Informe uma justificativa com ao menos 5 caracteres.');v.documents[key]={...d,applicability,applicabilityReason:reason};log(v,rule.name+': aplicabilidade '+applicability+' · '+reason);commit('Aplicabilidade registrada.')},'Salvar aplicabilidade')}
